import {describe, expect, it} from 'vitest';
import {AdapterModel, CHANNELS, ScenarioClock, hshifterLayout, seededId, type SdkAttribute, type SourceConfig} from '../../tools/telemetry-simulator/src/v1/source';

// Expectations are written from docs/protocol/v1.md §6/§8 and the "Records from the callbacks" table of
// docs/native-transport-v1.md; they are not generated by the adapter model under test.
const config = (over: Partial<SourceConfig> = {}): SourceConfig => ({game: 'ets2', seed: 'source-test', gameplayEvents: 'registered', currency: 'unknown', gameMode: 'unknown',
  versions: {telemetryApi: {major: 1, minor: 1}, gameTelemetry: {major: 1, minor: 19}, sdkArchive: 'scs-sdk-1.15'}, startEventSeq: 1n, ...over});
function adapter(over: Partial<SourceConfig> = {}) { const a = new AdapterModel(config(over), new ScenarioClock()); a.channel.gate = 'durable'; return a; }
const events = (a: AdapterModel) => a.channel.drain().flatMap(s => s.event ? [s.event] : []);
const records = (a: AdapterModel) => events(a).map(e => e.record) as unknown as Array<Record<string, unknown>>;
const str = (name: string, value: string | null): SdkAttribute => ({name, sdkType: 'string', value});
const clock0 = seededId('source-test', 'game-clock-0'), clock1 = seededId('source-test', 'game-clock-1');

describe('simulator v1 adapter records (D12, D13, TD-002)', () => {
  it('emits one event per job or truck callback, including identical re-sends (D13)', () => {
    const a = adapter(), job = [str('cargo.id', 'synthetic_cargo')];
    a.configuration('job', job, 'terminated', 0); a.configuration('job', job, 'terminated', 1); a.configuration('truck', [], 'terminated', 2);
    expect(events(a).map(e => [e.eventSeq, e.record.type, e.occurred.configurationRevision])).toEqual([[1n, 'job.configured', '1'], [2n, 'job.configured', '2'], [3n, 'truck.cleared', '3']]);
  });

  it('emits trailer events only for a non-empty slot or a clear after one, with the slot index (D13, OD-6)', () => {
    const a = adapter();
    a.configuration('trailer.3', [], 'terminated', 0);
    a.configuration('trailer.3', [str('id', 'trailer.synthetic')], 'terminated', 1);
    a.configuration('trailer.3', [], 'terminated', 2); a.configuration('trailer.3', [], 'terminated', 3);
    expect(records(a).map(r => [r.type, r.index])).toEqual([['trailer.configured', 3], ['trailer.cleared', 3]]);
    expect(a.channel.drain()).toEqual([]);
  });

  it('assigns no record and no eventSeq to bus and car jobs, the legacy trailer id, controls and car_job events (TD-002)', () => {
    const a = adapter();
    for (const id of ['bus_job', 'car_job', 'trailer', 'controls', 'hshifter', 'substances']) a.configuration(id, [str('id', 'x')], 'terminated', 0);
    for (const id of ['car_job.delivered', 'car_job.cancelled', 'unknown.event']) a.gameplay(id, [], 'terminated', 0);
    a.configuration('job', [], 'terminated', 1);
    const [only, ...rest] = events(a);
    expect([only.eventSeq, only.record.type, rest.length]).toEqual([1n, 'job.cleared', 0]);
    // Each ignored callback is still a boundary: nine of them precede the job clear.
    expect(only.occurred.boundaryOrder).toBe('10');
  });

  it('keeps provided empty text, marks missing text not-observed and invalid text invalid, never truncated (D12)', () => {
    const a = adapter();
    a.configuration('truck', [str('id', ''), str('brand_id', 'x'.repeat(129)), str('name', 'n'.repeat(256)), str('license.plate', null), str('brand', 'a\u0007b'),
      {name: 'license.plate.country.id', sdkType: 'u32', value: 7}], 'terminated', 0);
    expect(records(a)[0]).toMatchObject({id: {available: true, value: ''}, brandId: {available: false, reason: 'invalid'}, name: {available: true, value: 'n'.repeat(256)},
      licensePlate: {available: false, reason: 'invalid'}, brand: {available: false, reason: 'invalid'}, plateCountryId: {available: false, reason: 'invalid'},
      plateCountry: {available: false, reason: 'not-observed'}, fuelCapacity: {available: false, reason: 'not-observed', unit: 'L'}});
  });

  it('marks unseen fields invalid after a null or unterminated list; a null list is a present configuration', () => {
    const a = adapter();
    a.configuration('job', [], 'null', 0); a.configuration('job', [str('cargo.id', 'c')], 'unterminated', 1);
    const [nullList, cut] = records(a);
    expect(nullList).toMatchObject({type: 'job.configured', cargoId: {available: false, reason: 'invalid'}, plannedDistance: {available: false, reason: 'invalid', unit: 'm'}});
    expect(cut).toMatchObject({cargoId: {available: true, value: 'c'}, cargo: {available: false, reason: 'invalid'}});
  });

  it('applies the §6 mapping with exact money and documented currency per game (D11)', () => {
    for (const [game, code, header] of [['ets2', 'EUR', 'eurotrucks2/scssdk_telemetry_eut2.h'], ['ats', 'USD', 'amtrucks/scssdk_telemetry_ats.h']] as const) {
      const a = adapter({game, currency: 'sdk-documented'});
      a.configuration('job', [{name: 'planned_distance.km', sdkType: 'u32', value: 4_294_967_295}, {name: 'income', sdkType: 'u64', value: '18446744073709551615'},
        {name: 'cargo.mass', sdkType: 'float', value: 18_000.5}, {name: 'delivery.time', sdkType: 'u32', value: 13_000}, {name: 'cargo.unit.count', sdkType: 'u32', value: 0}], 'terminated', 0);
      a.gameplay('job.delivered', [{name: 'revenue', sdkType: 's64', value: '-9223372036854775808'}, {name: 'distance.km', sdkType: 'float', value: 152.5},
        {name: 'cargo.damage', sdkType: 'float', value: 0.03125}, {name: 'earned.xp', sdkType: 's32', value: 0}, {name: 'delivery.time', sdkType: 'u32', value: 471}], 'terminated', 1);
      const [job, delivered] = records(a), currency = {status: 'sdk-documented', code, source: `scs-sdk-1.15/include/${header}#game-specific-units`};
      expect(job).toMatchObject({plannedDistance: {available: true, value: 4_294_967_295_000, unit: 'm'}, cargoMass: {available: true, value: 18_000.5, unit: 'kg'},
        expectedIncome: {available: true, value: {raw: '18446744073709551615', sdkType: 'u64', currency}}, deliveryDeadline: {available: true, value: '13000', unit: 'min'},
        cargoUnitCount: {available: true, value: 0}});
      expect(delivered).toMatchObject({revenue: {available: true, value: {raw: '-9223372036854775808', sdkType: 's64', currency}}, distance: {available: true, value: 152_500, unit: 'm'},
        cargoDamage: {available: true, value: 0.03125, unit: 'fraction'}, earnedXp: {available: true, value: 0}, deliveryDuration: {available: true, value: '471', unit: 'min'},
        autoParkUsed: {available: false, reason: 'not-observed'}});
    }
    const unknown = adapter();
    unknown.gameplay('player.tollgate.paid', [{name: 'pay.amount', sdkType: 'u64', value: '5'}], 'terminated', 0);
    unknown.gameplay('player.fined', [{name: 'fine.amount', sdkType: 's64', value: '0'}], 'terminated', 0);
    expect(records(unknown)).toMatchObject([{amount: {available: false, reason: 'invalid'}}, {amount: {available: true, value: {raw: '0', sdkType: 's64', currency: {status: 'unknown'}}}}]);
  });

  it('maps channels to wire units, keeps zero distinct from unavailable and invalidates out-of-range readings (REG-009)', () => {
    const a = adapter();
    a.frame(false, {'speed': 0, 'fuel.amount': 410.5, 'odometer': 1234.5, 'fuel.consumption.average': 0.375, 'fuel.range': 1263, 'navigation.distance': 151_000,
      'displayed.gear': -1, 'engine.rpm': 'invalid', 'game.time': 4_294_967_295, 'world.placement': {x: -31_234.5, y: 42.25, z: 18_800.75, heading: 0.25, pitch: 0, roll: 2}}, 0);
    expect(a.published.state).toMatchObject({speed: {available: true, value: 0, unit: 'm/s'}, fuel: {available: true, value: 410.5, unit: 'L'}, odometer: {available: true, value: 1_234_500, unit: 'm'},
      averageConsumption: {available: true, value: 37.5, unit: 'L/100km'}, estimatedRange: {available: true, value: 1_263_000, unit: 'm'}, gear: {available: true, value: -1, unit: 'index'},
      engineRpm: {available: false, reason: 'invalid', unit: 'rpm'}, gameTime: {available: true, value: '4294967295', unit: 'min', clockId: clock0},
      worldPlacement: {available: false, reason: 'invalid'}, fuelCapacity: {available: false, reason: 'not-observed', unit: 'L'}});
    a.frame(false, {'speed': 2_000, 'displayed.gear': 101}, 10);
    expect(a.published.state).toMatchObject({speed: {available: false, reason: 'invalid'}, gear: {available: false, reason: 'invalid'}});
  });

  it('emits gameTime.regression with from/to across a rotated clock and occurs at `to` (save load, O10)', () => {
    const a = adapter();
    a.frame(false, {'game.time': 600, 'speed': 5, 'world.placement': {x: 1, y: 2, z: 3, heading: 0, pitch: 0, roll: 0}}, 0);
    a.frame(false, {'speed': 4, 'game.time': 300}, 10);
    const [r] = events(a);
    expect(r.record).toEqual({type: 'gameTime.regression', from: {minutes: {available: true, value: '600'}, clockId: clock0}, to: {minutes: {available: true, value: '300'}, clockId: clock1}});
    expect(r.occurred.gameTime).toEqual({minutes: {available: true, value: '300'}, clockId: clock1});
    // Channels observed earlier in the frame survive the rotation; unobserved ones are invalidated.
    expect(a.published.state).toMatchObject({speed: {available: true, value: 4}, worldPlacement: {available: false, reason: 'not-observed'}, gameTime: {value: '300', clockId: clock1}});
  });

  it('emits timers.restart at frame start with game time not observed under the new clock', () => {
    const a = adapter();
    a.frame(false, {'game.time': 600, 'fuel.amount': 100}, 0); a.frame(true, {'speed': 3}, 10);
    const [r] = events(a);
    expect(r.record).toEqual({type: 'timers.restart'});
    expect(r.occurred.gameTime).toEqual({minutes: {available: false, reason: 'not-observed'}, clockId: clock1});
    expect(a.published.state).toMatchObject({fuel: {available: false, reason: 'not-observed'}, speed: {available: true, value: 3}, gameTime: {available: false, clockId: clock1}});
  });

  it('records the simulation state after the callback and counts offline boundaries only with no client (OD-5 S10)', () => {
    const a = adapter(); a.channel.gate = 'none';
    a.lifecycle('simulation.paused', 0); a.configuration('job', [], 'terminated', 1); a.gameplay('player.fined', [], 'terminated', 2);
    a.configuration('bus_job', [], 'terminated', 3);
    a.channel.gate = 'live'; a.lifecycle('simulation.started', 4);
    a.channel.gate = 'durable'; a.lifecycle('simulation.paused', 5); a.frame(false, {}, 6);
    expect(a.published.offlineTransitions).toBe(2n);
    const [slot] = a.channel.drain();
    expect(slot.lossBefore).toEqual({first: 1n, last: 4n, counts: {offline: 3n, noDurableConsumer: 1n, queueCount: 0n}, firstNs: 1_000_000_000_000n, lastNs: 1_000_004_000_000n});
    expect(slot.event?.occurred.simulation).toBe('paused');
    expect(slot.event?.occurred.boundaryOrder).toBe('6');
  });

  it('keeps a loss run open while the handoff is full, then flushes it at frame end (OD-5 S4)', () => {
    const a = adapter(); a.channel.full = true;
    a.lifecycle('simulation.started', 0); a.frame(false, {}, 1);
    expect(a.channel.drain()).toEqual([]);
    a.channel.full = false; a.frame(false, {}, 2);
    expect(a.channel.drain()).toEqual([{lossBefore: {first: 1n, last: 1n, counts: {offline: 0n, noDurableConsumer: 0n, queueCount: 1n}, firstNs: 1_000_000_000_000n, lastNs: 1_000_000_000_000n}}]);
  });
});

// ET-050b B2: the minor-1 gearbox, with the native adapter's copy rules and its encoder's bounds
// (docs/native-transport-v1.md, Gearbox capture). Layouts are written by hand.
describe('simulator v1 gearbox capture (ET-050b)', () => {
  const u32 = (name: string, value: number, index?: number): SdkAttribute => ({name, sdkType: 'u32', value, ...(index === undefined ? {} : {indexed: true, index})});
  const s32 = (name: string, value: number, index: number): SdkAttribute => ({name, sdkType: 's32', value, indexed: true, index});
  /** SDK slot attributes in slot order; selector.count is sent twice, without an index and at index 0, as in CAP-01. */
  const layout = (slots: [number, number, number][], count = 2) => [u32('selector.count', count), u32('selector.count', count, 0),
    ...slots.flatMap(([gear, handle, selectors], i) => [s32('slot.gear', gear, i), u32('slot.handle.position', handle, i), u32('slot.selectors', selectors, i)])];
  const neutral: [number, number, number][] = [[0, 0, 0], [0, 0, 1], [0, 0, 2], [0, 0, 3]];
  const twelve: [number, number, number][] = [[-1, 1, 0], [-3, 1, 1], [-2, 1, 2], [-4, 1, 3], [1, 2, 0], [7, 2, 1], [2, 2, 2], [8, 2, 3], [3, 3, 0], [9, 3, 1], [4, 3, 2], [10, 3, 3]];
  const expectSlots = (slots: [number, number, number][]) => slots.filter(([gear]) => gear !== 0).map(([gear, handlePosition, selectors]) => ({gear, handlePosition, selectors}));
  const invalid = {available: false, reason: 'invalid'};

  it('lists every nonzero slot in SDK slot order and omits neutral slots', () => {
    expect(hshifterLayout(layout([...neutral, ...twelve]), 'terminated')).toEqual({available: true, value: {selectorCount: 2, slots: expectSlots(twelve)}});
    // An all-neutral layout is a valid, empty one; an empty list is not-observed.
    expect(hshifterLayout(layout(neutral), 'terminated')).toEqual({available: true, value: {selectorCount: 2, slots: []}});
    expect(hshifterLayout([], 'terminated')).toEqual({available: false, reason: 'not-observed'});
  });
  it.each<[string, SdkAttribute[], 'terminated' | 'null' | 'unterminated']>([
    ['a null list', [], 'null'],
    ['an unterminated list', layout(twelve), 'unterminated'],
    ['a duplicate pair between a neutral and a nonzero slot', layout([[0, 2, 0], [1, 2, 0]]), 'terminated'],
    ['a duplicate pair between two neutral slots', layout([[0, 0, 0], [0, 0, 0], [1, 1, 0]]), 'terminated'],
    ['disagreeing selector counts', [u32('selector.count', 2), u32('selector.count', 1, 0), s32('slot.gear', 1, 0), u32('slot.handle.position', 1, 0), u32('slot.selectors', 0, 0)], 'terminated'],
    ['a missing selector count', layout(twelve).slice(2), 'terminated'],
    ['a selector count of 7', layout([[1, 1, 0]], 7), 'terminated'],
    ['selectors not below 2^selectorCount', layout([[1, 1, 4]]), 'terminated'],
    ['a slot without its selectors', layout([[1, 1, 0]]).slice(0, -1), 'terminated'],
    ['a repeated slot attribute', [...layout([[1, 1, 0]]), s32('slot.gear', 2, 0)], 'terminated'],
    ['a slot attribute without an index', [...layout([[1, 1, 0]]), {name: 'slot.gear', sdkType: 's32', value: 2}], 'terminated'],
    ['a slot index of 64', [u32('selector.count', 0), s32('slot.gear', 1, 64), u32('slot.handle.position', 1, 64), u32('slot.selectors', 0, 64)], 'terminated'],
    ['a gear of 101', layout([[101, 1, 0]]), 'terminated'],
    ['a handle position of 256', layout([[1, 256, 0]]), 'terminated'],
    ['a wrong-typed slot gear', [u32('selector.count', 0), u32('slot.gear', 1, 0), u32('slot.handle.position', 1, 0), u32('slot.selectors', 0, 0)], 'terminated']
  ])('marks %s invalid, never truncated', (_name, attributes, list) => {
    expect(hshifterLayout(attributes, list)).toEqual(invalid);
  });
  it('accepts 64 slots and ignores shifter.type and other attributes', () => {
    const slots = Array.from({length: 64}, (_, i): [number, number, number] => [1, i, 0]);
    expect(hshifterLayout([{name: 'shifter.type', sdkType: 'string', value: 'name-1'}, ...layout(slots, 0)], 'terminated')).toEqual({available: true, value: {selectorCount: 0, slots: expectSlots(slots)}});
  });
  it('copies the gear counts from the truck callback and keeps the layout across truck changes (B2)', () => {
    const a = adapter();
    // The SDK sends hshifter before truck in a burst (CAP-01 run2, run4): the truck must not clear the layout.
    a.configuration('hshifter', layout(twelve), 'terminated', 0);
    a.configuration('truck', [str('id', 'vehicle.a'), u32('gears.forward', 12), u32('gears.reverse', 4)], 'terminated', 1);
    a.frame(false, {}, 2);
    expect(a.published.gearbox).toEqual({forwardGears: {available: true, value: 12}, reverseGears: {available: true, value: 4}, hshifter: {available: true, value: {selectorCount: 2, slots: expectSlots(twelve)}}});
    // No record, eventSeq or revision for the hshifter callback: only the truck callback emitted.
    expect(events(a).map(e => [e.record.type, e.occurred.configurationRevision])).toEqual([['truck.configured', '1']]);
    // A truck change without the counts, a clear, counts above 100 or wrong-typed, and a null list.
    a.configuration('truck', [str('id', 'vehicle.b')], 'terminated', 3); a.frame(false, {}, 4);
    expect(a.published.gearbox).toMatchObject({forwardGears: {available: false, reason: 'not-observed'}, hshifter: {available: true}});
    a.configuration('truck', [], 'terminated', 5); a.frame(false, {}, 6);
    expect(a.published.gearbox).toMatchObject({forwardGears: {available: false, reason: 'not-observed'}, reverseGears: {available: false, reason: 'not-observed'}, hshifter: {available: true}});
    a.configuration('truck', [u32('gears.forward', 101), {name: 'gears.reverse', sdkType: 's32', value: 4}], 'terminated', 7); a.frame(false, {}, 8);
    expect(a.published.gearbox).toMatchObject({forwardGears: invalid, reverseGears: invalid});
    a.configuration('truck', [], 'null', 9); a.frame(false, {}, 10);
    expect(a.published.gearbox).toMatchObject({forwardGears: invalid, reverseGears: invalid});
    // A later hshifter callback replaces the layout; an empty one makes it not-observed.
    a.configuration('hshifter', [], 'terminated', 11); a.frame(false, {}, 12);
    expect(a.published.gearbox.hshifter).toEqual({available: false, reason: 'not-observed'});
    // The published state itself never carries the gearbox; the producer adds it on minor-1 connections only.
    expect(Object.hasOwn(a.published.state, 'gearbox')).toBe(false);
  });
});

// ET-052: the optional `mandatory.break` channel, with the native adapter's rules (docs/native-transport-v1.md, "Callback
// capture"): s32 game minutes, signed and unclamped, zero a value, a callback without a value not-observed, a refused
// registration not-supported, and a copy that does not advance the shared boundary order.
describe('simulator v1 mandatory break capture (ET-052)', () => {
  const breakOf = (a: AdapterModel) => a.published.nextMandatoryBreak;
  it('lists the channel before the placement in registration order', () => {
    expect(CHANNELS.slice(-2)).toEqual(['mandatory.break', 'world.placement']);
    expect(CHANNELS.indexOf('mandatory.break')).toBeGreaterThan(CHANNELS.indexOf('navigation.distance'));
  });
  it('is not-observed before any callback and carries each s32 value exactly, zero and negative included', () => {
    const a = adapter();
    expect(breakOf(a)).toEqual({available: false, reason: 'not-observed', unit: 'min'});
    for (const value of [95, 0, -30, 2147483647, -2147483648, 1]) {
      a.frame(false, {'mandatory.break': value}, 0);
      expect([value, breakOf(a)]).toEqual([value, {available: true, value, unit: 'min'}]);
    }
  });
  it('maps a callback without a value to not-observed and a wrong-typed one to invalid, then recovers', () => {
    const a = adapter();
    a.frame(false, {'mandatory.break': 40}, 0); a.frame(false, {'mandatory.break': null}, 1);
    expect(breakOf(a)).toEqual({available: false, reason: 'not-observed', unit: 'min'});
    a.frame(false, {'mandatory.break': 'invalid'}, 2);
    expect(breakOf(a)).toEqual({available: false, reason: 'invalid', unit: 'min'});
    a.frame(false, {'mandatory.break': 3}, 3);
    expect(breakOf(a)).toEqual({available: true, value: 3, unit: 'min'});
  });
  it('keeps the last reading while later frames list other channels only, as the native adapter does', () => {
    const a = adapter();
    a.frame(false, {'mandatory.break': 61}, 0); a.frame(false, {speed: 5}, 1);
    expect(breakOf(a)).toEqual({available: true, value: 61, unit: 'min'});
  });
  it('clears the reading at a timer restart and at a truck configuration unless the new frame delivers it, and keeps it when it does', () => {
    const a = adapter();
    a.frame(false, {'mandatory.break': 61}, 0); a.frame(true, {}, 1);
    expect(breakOf(a)).toEqual({available: false, reason: 'not-observed', unit: 'min'});
    a.frame(false, {'mandatory.break': 61}, 2); a.frame(true, {'mandatory.break': 50}, 3);
    expect(breakOf(a)).toEqual({available: true, value: 50, unit: 'min'});
    a.configuration('truck', [], 'terminated', 4); a.frame(false, {}, 5);
    expect(breakOf(a)).toEqual({available: false, reason: 'not-observed', unit: 'min'});
  });
  it('reports not-supported whatever a frame lists when the registration is refused, and never as zero', () => {
    const a = adapter({mandatoryBreak: 'not-supported'});
    expect(breakOf(a)).toEqual({available: false, reason: 'not-supported', unit: 'min'});
    a.frame(false, {'mandatory.break': 95}, 0);
    expect(breakOf(a)).toEqual({available: false, reason: 'not-supported', unit: 'min'});
    expect(breakOf(adapter({mandatoryBreak: 'registered'}))).toEqual({available: false, reason: 'not-observed', unit: 'min'});
  });
  it('does not advance the shared boundary order, so the v1 state of a game that provides the channel matches one that does not', () => {
    const without = adapter(), withBreak = adapter();
    without.frame(false, {speed: 9}, 0); withBreak.frame(false, {speed: 9, 'mandatory.break': 95}, 0);
    expect(withBreak.published.state.boundaryOrder).toBe(without.published.state.boundaryOrder);
    expect(withBreak.published.state).toEqual(without.published.state);
    // The published state itself never carries the break; the producer adds it on minor-2 connections only.
    expect(Object.hasOwn(withBreak.published.state, 'nextMandatoryBreak')).toBe(false);
  });
  it('emits no record, event or eventSeq for the channel', () => {
    const a = adapter();
    a.frame(false, {'mandatory.break': 95}, 0);
    expect(a.channel.drain()).toEqual([]);
    expect(a.channel.nextEventSeq).toBe(1n);
  });
});
